mapper.select:


    and i.project_id = #{projectId}
    and i.work_package_id = #{workPackageId}
    and i.task_id = #{taskId}
    and i.status = #{status}
    and i.issue_name like concat('%', #{issueName}, '%')
    and (i.reporter_user_id=#{viewerUserId} or i.owner_user_id=#{viewerUserId}
      or exists(select 1 from pm_project p where p.project_id=i.project_id and p.manager_id=#{viewerUserId})
      or exists(select 1 from pm_project_member m where m.project_id=i.project_id
                and m.user_id=#{viewerUserId} and m.status='ACTIVE'))

order by i.issue_id desc
